"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import api from "@/lib/axios";
import { Loader2, Plus, Trash2, ArrowLeft } from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";

const CATEGORIES = [
    { value: "daily", label: "Daily" },
    { value: "festival", label: "Festival" },
    { value: "vratham", label: "Vratham" },
    { value: "homam", label: "Homam" },
    { value: "special", label: "Special" },
];

export default function NewProductPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [form, setForm] = useState({
        title: "",
        shortDescription: "",
        category: "daily",
        image: "",
        marketPrice: "",
        offerPrice: "",
    });
    const [items, setItems] = useState<{ id: number; text: string }[]>([]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.title.trim()) { toast.error("Title is required"); return; }
        if (!form.category) { toast.error("Category is required"); return; }

        try {
            setLoading(true);
            await api.post("/vendor/products", {
                ...form,
                marketPrice: form.marketPrice ? Number(form.marketPrice) : undefined,
                offerPrice: form.offerPrice ? Number(form.offerPrice) : undefined,
                itemsIncluded: items.filter(i => i.text.trim()),
            });
            toast.success("Product created. Pending admin approval.");
            router.push("/dashboard/products");
        } catch {
            toast.error("Failed to create product");
        } finally {
            setLoading(false);
        }
    };

    const addItem = () => setItems([...items, { id: Date.now(), text: "" }]);
    const removeItem = (id: number) => setItems(items.filter(i => i.id !== id));
    const updateItem = (id: number, text: string) => setItems(items.map(i => i.id === id ? { ...i, text } : i));

    return (
        <div className="space-y-6 pb-8 max-w-2xl">
            <div className="flex items-center gap-3">
                <Link href="/dashboard/products">
                    <Button size="sm" variant="ghost"><ArrowLeft className="w-4 h-4" /></Button>
                </Link>
                <div>
                    <div className="flex items-center gap-2 text-xs text-muted-foreground">
                        <span>Products</span><span>/</span><span className="text-[#8D0303] font-medium">New</span>
                    </div>
                    <h1 className="text-xl font-bold">Add Product</h1>
                </div>
            </div>

            <form onSubmit={handleSubmit}>
                <Card className="border shadow-sm">
                    <CardContent className="p-6 space-y-4">
                        <div>
                            <Label>Title *</Label>
                            <Input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="e.g. Daily Pooja Kit" className="mt-1" />
                        </div>
                        <div>
                            <Label>Short Description</Label>
                            <Input value={form.shortDescription} onChange={(e) => setForm({ ...form, shortDescription: e.target.value })} placeholder="Brief description..." className="mt-1" />
                        </div>
                        <div>
                            <Label>Category *</Label>
                            <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className="mt-1 w-full h-10 rounded-md border border-input bg-background px-3 text-sm">
                                {CATEGORIES.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                            </select>
                        </div>
                        <div>
                            <Label>Image URL</Label>
                            <Input value={form.image} onChange={(e) => setForm({ ...form, image: e.target.value })} placeholder="https://..." className="mt-1" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <Label>Market Price (₹)</Label>
                                <Input type="number" value={form.marketPrice} onChange={(e) => setForm({ ...form, marketPrice: e.target.value })} placeholder="999" className="mt-1" />
                            </div>
                            <div>
                                <Label>Offer Price (₹)</Label>
                                <Input type="number" value={form.offerPrice} onChange={(e) => setForm({ ...form, offerPrice: e.target.value })} placeholder="799" className="mt-1" />
                            </div>
                        </div>

                        <div>
                            <div className="flex items-center justify-between mb-2">
                                <Label>Items Included</Label>
                                <Button type="button" size="sm" variant="outline" onClick={addItem}>
                                    <Plus className="w-3 h-3 mr-1" /> Add Item
                                </Button>
                            </div>
                            {items.map((item) => (
                                <div key={item.id} className="flex items-center gap-2 mb-2">
                                    <Input value={item.text} onChange={(e) => updateItem(item.id, e.target.value)} placeholder="Item name..." className="flex-1" />
                                    <Button type="button" size="sm" variant="ghost" onClick={() => removeItem(item.id)}>
                                        <Trash2 className="w-3 h-3 text-red-500" />
                                    </Button>
                                </div>
                            ))}
                        </div>

                        <div className="flex gap-3 pt-4">
                            <Button type="submit" className="bg-[#8D0303] hover:bg-[#700202] text-white" disabled={loading}>
                                {loading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
                                Create Product
                            </Button>
                            <Link href="/dashboard/products">
                                <Button type="button" variant="outline">Cancel</Button>
                            </Link>
                        </div>
                    </CardContent>
                </Card>
            </form>
        </div>
    );
}
